// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    // Fuzzed actor is any address; property: only owner (the deployer) can successfully call sudicideAnyone.
    function testFuzz_property(address actor) public {
        // keep actor wide but not zero-address to be meaningful
        vm.assume(actor != address(0));

        // fund the actor so calls with value would be possible (not needed here, but harmless)
        vm.deal(actor, 1 ether);

        // The owner is the deployer of c which is address(this) in setUp; ensure actor is not the owner
        // If the fuzzer happens to pick the owner address, the call should succeed; we only assert that
        // non-owner callers cannot successfully execute sudicideAnyone.
        if (actor == address(this)) {
            // when actor is owner, the call should succeed; ensure that by actually calling from owner
            bool ok;
            try c.sudicideAnyone() {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(ok);
            return;
        }

        // non-owner: the reference contract requires only-owner, so call must revert (ok == false)
        bool ok;
        vm.prank(actor);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // SINGLE ASSERT: reference satisfies that non-owner calls fail for all actor != owner; mutant removing the modifier will let some non-owner succeed
        assertTrue(!ok);
    }
}
